var cssparser = (function() {
    function Parser(css) {
        this.css = css;
        this.index = 0;
    }

    Parser.prototype = {
        parse: function() {
            var rules = [];
            this.skipWhitespace();
            while (!this.isEOF()) {
                rules.push(this.parseRule());
            }
            return rules;
        },

        parseRule: function() {
            var selector = this.parseSelector();
            var declarations = this.parseDeclarationList();
            return { selector: selector, declarations: declarations };
        },

        parseSelector: function() {
            var selector = "";
            this.skipWhitespace();
            while (!this.isEOF() && this.peek() !== "{" && this.peek() !== ";") {
                var ch = this.next();
                selector += ch === "\n" ? " " : ch;
            }
            return selector.trim();
        },

        parseDeclarationList: function() {
            this.skipWhitespace();
            if (!this.consume("{")) return [];
            var declarations = [];
            this.skipWhitespace();
            while (!this.isEOF() && !this.peekIs("}")) {
                var decl = this.parseDeclaration();
                if (decl) declarations.push(decl);
                this.skipWhitespace();
                this.consume(";");
            }
            this.consume("}");
            return declarations;
        },

        parseDeclaration: function() {
            var property = this.parseProperty();
            this.skipWhitespace();
            if (!this.consume(":")) return null;
            this.skipWhitespace();
            var value = this.parseValue();
            return { property: property, value: value };
        },

        parseProperty: function() {
            var property = "";
            while (!this.isEOF() && this.isPropertyChar(this.peek())) {
                property += this.next();
            }
            return property.trim();
        },

        parseValue: function() {
            var value = "";
            this.skipWhitespace();
            while (!this.isEOF() && this.peek() !== ";" && this.peek() !== "}") {
                var ch = this.next();
                value += ch === "\n" ? " " : ch;
            }
            return value.trim();
        },

        isPropertyChar: function(ch) {
            return /[a-zA-Z0-9\-_]/.test(ch);
        },

        peek: function() {
            return this.css[this.index] || "";
        },

        peekIs: function(ch) {
            return this.peek() === ch;
        },

        consume: function(ch) {
            if (this.peek() === ch) {
                this.index++;
                return true;
            }
            return false;
        },

        next: function() {
            var ch = this.peek();
            this.index++;
            return ch;
        },

        skipWhitespace: function() {
            while (/^\s$/.test(this.peek())) {
                this.next();
            }
        },

        isEOF: function() {
            return this.index >= this.css.length;
        }
    };

    return function(css) {
        var parser = new Parser(css);
        return parser.parse();
    };
})();